import {Injectable,inject} from "@angular/core";
import {Actions,createEffect,ofType} from "@ngrx/effects";
import {map} from "rxjs";
import {loadBooks,booksLoaded} from "./state";
@Injectable()
export class BookEffects{private actions=inject(Actions);load=createEffect(()=>this.actions.pipe(ofType(loadBooks),map(()=>booksLoaded({titles:["Moon Trip"]}))));}
